toolScript:
let batteryObj = null;
        let isLogging = false;
        let logData = [];
        let startTime = null;
        let chart = null;
        // Initialize Chart
        function initChart() {
            const ctx = document.getElementById('batteryChart').getContext('2d');
            chart = new Chart(ctx, {
                type: 'line',
                data: {
                    labels: [],
                    datasets: [{
                        label: 'Battery Level %',
                        data: [],
                        borderColor: '#0ea5e9',
                        backgroundColor: 'rgba(14, 165, 233, 0.05)',
                        borderWidth: 4,
                        pointRadius: 0,
                        tension: 0.4,
                        fill: true
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: { legend: { display: false } },
                    scales: {
                        y: {
                            min: 0,
                            max: 100,
                            grid: { color: '#f1f5f9' },
                            ticks: { font: { weight: 'bold', family: 'JetBrains Mono' } }
                        },
                        x: { display: false }
                    }
                }
            });
        }
        async function startLogging() {
            if (!('getBattery' in navigator)) {
                showToast("Hardware API restricted: Chromium-based browser required.");
                return;
            }
            if (!isLogging) {
                batteryObj = await navigator.getBattery();
                isLogging = true;
                startTime = Date.now();
                document.getElementById('start-btn').innerText = "SUSPEND TELEMETRY";
                document.getElementById('start-btn').classList.replace('bg-sky-500', 'bg-rose-500');
                showToast("Telemetry stream initialized.");
                logTick();
            } else {
                isLogging = false;
                document.getElementById('start-btn').innerText = "RESUME TELEMETRY";
                document.getElementById('start-btn').classList.replace('bg-rose-500', 'bg-sky-500');
                showToast("Stream suspended.");
            }
        }
        function logTick() {
            if (!isLogging || !batteryObj) return;
            const now = Date.now();
            const level = batteryObj.level * 100;
            const elapsed = Math.floor((now - startTime) / 1000);
            // Update UI Stats
            document.getElementById('live-level').innerText = level.toFixed(0) + "%";
            document.getElementById('live-source').innerText = batteryObj.charging ? "AC POWER" : "BATTERY";
            document.getElementById('elapsed-time').innerText = formatElapsed(elapsed);
            // Update Graph
            chart.data.labels.push(elapsed);
            chart.data.datasets[0].data.push(level);
            if (chart.data.labels.length > 60) { // Keep last 5 minutes of data
                chart.data.labels.shift();
                chart.data.datasets[0].data.shift();
            }
            chart.update('none');
            // Calculate Rate
            // Formula Logic: Rate = (Initial % - Final %) / (Elapsed hours)
            if (chart.data.datasets[0].data.length > 2) {
                const firstVal = chart.data.datasets[0].data[0];
                const lastVal = chart.data.datasets[0].data[chart.data.datasets[0].data.length - 1];
                const drop = firstVal - lastVal;
                const hoursElapsed = elapsed / 3600;
                if (hoursElapsed > 0.001) { // Prevent division by tiny numbers
                    const rate = (drop / hoursElapsed).toFixed(2);
                    document.getElementById('current-drain').innerHTML = `${Math.abs(rate)}<span class="drain-unit">%/hr</span>`;
                }
            }
            setTimeout(logTick, 5000); // Higher polling rate for precision
        }
        function formatElapsed(s) {
            const m = Math.floor(s / 60);
            return `${m}m ${s % 60}s`;
        }
        function resetLog() {
            if (!confirm("Purge telemetry cache?")) return;
            logData = [];
            startTime = Date.now();
            chart.data.labels = [];
            chart.data.datasets[0].data = [];
            chart.update();
            document.getElementById('current-drain').innerHTML = `0.00<span class="drain-unit">%/hr</span>`;
            showToast("Cache purged.");
        }
        function showToast(msg) {
            const toast = document.createElement('div');
            toast.className = "fixed top-24 left-1/2 -translate-x-1/2 bg-slate-800 text-white px-8 py-3 rounded-full shadow-2xl z-[100] animate-bounce font-black text-xs uppercase tracking-widest";
            toast.innerText = msg;
            document.body.appendChild(toast);
            setTimeout(() => toast.remove(), 4000);
        }
        // Initialize Scroll to Top
        window.onload = initChart;
